('983bd933-e784-56e1-a4ff-e3790988495c', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'JSlider permite principalmente:', '["Editar parágrafos.","Serializar dados.","Abrir uma conexão JDBC.","Escolher um arquivo.","Selecionar um valor em um intervalo."]'::jsonb, 4, 'O componente pode exibir marcas e rótulos de escala.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.2, páginas 747–749 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('79128aaa-824a-561c-a255-b2a5d393e188', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Qual ouvinte acompanha mudanças de valor de JSlider?', '["MouseWheelListener obrigatoriamente.","Runnable.","Serializable.","ChangeListener.","WindowListener."]'::jsonb, 3, 'StateChanged é chamado para mudanças acompanhadas pelo modelo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.2, páginas 747–749 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7a049cfb-30cf-5a2b-8006-43261f88a312', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Qual método consulta o valor atual do JSlider?', '["getSelectedFile().","nextInt().","readObject().","getText().","getValue()."]'::jsonb, 4, 'O valor é numérico no modelo do controle.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.2, páginas 747–749 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('29b8ca32-361d-542d-a86f-cd0f5629c029', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'WindowListener trata eventos relacionados a:', '["Ciclo e estado de janelas.","Somente teclas.","Apenas pintura de pixels.","Exclusivamente arquivos.","Somente SQL."]'::jsonb, 0, 'Abertura e fechamento são exemplos desses eventos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.3, páginas 750 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4237cf3d-2c53-5b3a-854d-def271e6beb5', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'WindowAdapter permite:', '["Impedir fechamento físico da JVM sempre.","Eliminar qualquer registro do ouvinte.","Transformar JFrame em array.","Sobrescrever apenas callbacks de janela de interesse.","Executar JDBC."]'::jsonb, 3, 'A classe fornece implementações vazias para facilitar especialização.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.3, páginas 750 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a59a733c-9fc4-5fc2-9f79-5dc90f819736', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'JMenuBar serve principalmente para:', '["Abrir uma transação.","Gerenciar uma pilha.","Conter menus de uma janela.","Conter apenas texto editável.","Representar um arquivo."]'::jsonb, 2, 'Menus e itens organizam ações disponíveis ao usuário.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.4, páginas 751–756 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('074367ac-269c-5baf-9089-53ddfae81f0e', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'JMenuItem representa normalmente:', '["Uma janela principal.","Um array de menus.","Uma opção acionável de menu.","Um gerador de fontes.","Uma árvore de arquivos obrigatória."]'::jsonb, 2, 'O item pode disparar eventos de ação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.4, páginas 751–756 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b6252201-21dd-5eb6-a618-19c763c39e4b', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Uma tecla mnemônica de menu tem como finalidade:', '["Fechar toda janela.","Ordenar automaticamente itens.","Facilitar acionamento por teclado.","Cifrar o texto.","Serializar o menu."]'::jsonb, 2, 'A navegação por teclado é parte da interação com menus.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.4, páginas 751–756 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fd4e6809-e1ed-50e5-8737-15a6552ce0ce', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'JCheckBoxMenuItem permite ao item de menu manter:', '["Uma thread.","Estado de seleção independente.","Uma transação obrigatória.","Um arquivo aberto.","Somente texto sem estado."]'::jsonb, 1, 'O estado é semelhante ao de uma caixa de seleção.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.4, páginas 751–756 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c0e36624-7aa6-56b9-9aac-345a1f9fe034', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'JRadioButtonMenuItem agrupado é útil para:', '["Entrada livre de parágrafos.","Qualquer número de escolhas simultâneas obrigatórias.","Uma árvore binária.","Uma barra de progresso.","Escolhas mutuamente exclusivas."]'::jsonb, 4, 'Um grupo apropriado coordena a exclusão mútua.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.4, páginas 751–756 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('818c89a4-4012-5063-a302-475ec5cf3095', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'JPopupMenu apresenta normalmente:', '["Um editor de código.","Um menu contextual.","Um mapa hash.","Um layout de grade obrigatória.","Um arquivo binário."]'::jsonb, 1, 'O contexto de interação determina as ações pertinentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.5, páginas 757–758 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('05f32a1b-219f-5127-a32d-5a526c6e71ed', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'Para menu contextual portável, o evento pode ser verificado com:', '["isClosed() da conexão.","isEmpty() do arquivo.","isSerializable().","isPopupTrigger().","isDaemon()."]'::jsonb, 3, 'O momento do gatilho pode variar entre plataformas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.5, páginas 757–758 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a88d5c22-a3c6-5388-aac0-9de968e6a8f8', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Aparência e comportamento plugáveis em Swing permitem:', '["Substituir qualquer sistema operacional.","Mudar a sintaxe da linguagem.","Converter interfaces em primitivas.","Eliminar todas as regras de eventos.","Alterar a apresentação dos componentes por implementações de look and feel."]'::jsonb, 4, 'A lógica da aplicação não precisa ser reescrita para cada aparência.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.6, páginas 759–762 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('abb74ece-b803-52bc-b62e-ea754e3994e6', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'UIManager é associado principalmente ao gerenciamento de:', '["Classes genéricas.","Árvores de busca.","Configurações de aparência de Swing.","Arquivos serializados.","Conexões SQL."]'::jsonb, 2, 'A escolha de look and feel é um de seus usos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.6, páginas 759–762 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c9437e42-a786-5f7c-9a12-24692b635f9f', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'JDesktopPane e JInternalFrame apoiam:', '["Janelas internas em uma área de trabalho.","Serialização automática.","Exclusivamente desenhos 3D.","Criação de processos do sistema operacional.","Somente entrada de teclado."]'::jsonb, 0, 'JInternalFrame fica dentro do contêiner da aplicação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.7, páginas 763–765 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cfb84d26-b77e-53b0-81e2-cd7749b1ba59', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'JInternalFrame é equivalente a um JFrame de nível superior independente?', '["Sim, em qualquer contexto.","Não, é uma janela interna em outro contêiner.","Não, porque não pode conter componentes.","Somente quando tem título.","Sim, porque ambos usam int."]'::jsonb, 1, 'O escopo visual e a contenção são diferentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.7, páginas 763–765 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1ad2291b-9f11-59c9-a877-2ff5a694d1b6', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'JTabbedPane organiza componentes em:', '["Uma fila sem interface.","Abas selecionáveis.","Somente menus de contexto.","Um conjunto sem ordem.","Um arquivo por linha."]'::jsonb, 1, 'Cada aba dá acesso ao painel correspondente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.8, páginas 766–767 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('69649e91-fa77-5618-843a-9ce6a1db2a82', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'BoxLayout organiza componentes principalmente:', '["Ao longo de um eixo.","Somente nas cinco regiões de BorderLayout.","Apenas por posições absolutas.","Em ordem aleatória.","Sempre em células iguais."]'::jsonb, 0, 'O eixo pode orientar a disposição horizontal ou vertical.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.9, páginas 768–770 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d31d03d1-e188-50a1-af32-def7daf6aa8e', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'GridBagLayout oferece:', '["Grade flexível com restrições de posicionamento e tamanho.","Somente uma coluna fixa.","Exclusivamente abas.","Somente sobreposição livre.","Apenas cinco regiões."]'::jsonb, 0, 'Restrições descrevem como cada componente participa da grade.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.10, páginas 771–777 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9c11b242-595c-5a3d-915b-9c4cb306a252', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'GridBagConstraints é usada para:', '["Executar uma thread.","Criar um Slider.","Descrever uma consulta SQL.","Especificar restrições de um componente no GridBagLayout.","Definir uma exceção."]'::jsonb, 3, 'Dados como posição, extensão e preenchimento controlam a disposição.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 22, seção 22.10, páginas 771–777 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
